root=Path('/workspace');r=json.loads((root/'runtime.json').read_text());p=json.loads((root/'proposal.json').read_text())
# Validate the exposed JSON-schema subset with standard library only.
def validate(value,schema,path='study'):
 typ=schema.get('type')
 if typ:
  types={'object':dict,'array':list,'string':str,'boolean':bool}
  assert isinstance(value,types[typ]),(path,'type',typ)
 if 'const' in schema: assert value==schema['const'],(path,'const')
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=value.keys(),(path,'required')
  if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),(path,'extra')
  for k,v in value.items():
   if k in schema.get('properties',{}):validate(v,schema['properties'][k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),(path,'minItems')
  for i,v in enumerate(value):validate(v,schema.get('items',{}),path+f'[{i}]')
 if isinstance(value,str):assert len(value)>=schema.get('minLength',0),(path,'minLength')
validate(p['study'],r['study_schema'])
assert set(p)=={'study','parent_trial','variants'}
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
history_ids={t['id'] for t in r['context']['history']}
assert p['parent_trial'] in history_ids
assert set(p['study']['evidence_refs'])<=history_ids
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
def methods(path):
 tree=ast.parse(path.read_text());compile(tree,str(path),'exec')
 return tree,{n.name:ast.dump(n) for c in tree.body if isinstance(c,ast.ClassDef) for n in c.body if isinstance(n,ast.FunctionDef)}
base_tree,base=methods(root/'baseline_reference.py')
old_tree,old=methods(root/'history_r0001_count_corrected_din.py')
class_asts=[]
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert v['role'] in ('candidate','control')
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 path=root/v['file'];t,m=methods(path)
 config=ast.literal_eval(next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets)))
 assert config==v['config']
 assert m['__init__']==base['__init__']
 for name in ('_encode','_type_counts','_scores'):assert m[name]==old[name],name
 for n in ast.walk(t):
  if isinstance(n,ast.Import):assert all(x.name=='torch' for x in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module=='torch'
  if isinstance(n,ast.Name):assert n.id not in {'open','eval','exec','__import__','compile','getattr','globals','locals','os','sys','subprocess'}
 class_asts.append(ast.dump(next(n for n in t.body if isinstance(n,ast.ClassDef))))
 print(v['file'],'syntax/config/import checks pass; unchanged learned initialization and encoding; sha256',hashlib.sha256(path.read_bytes()).hexdigest())
assert len(set(class_asts))==1
# Independently check the proposed mathematical intervention, not Torch execution.
def weights(scores,types,mask,alpha):
 counts={b:sum(m and t==b for t,m in zip(types,mask)) for b in range(1,5)}
 adjusted=[s-alpha*math.log(max(counts.get(t,0),1)) if m else -math.inf for s,t,m in zip(scores,types,mask)]
 mx=max(adjusted,default=-math.inf)
 if mx==-math.inf:return [0.0]*len(mask)
 z=[math.exp(x-mx) if m else 0.0 for x,m in zip(adjusted,mask)]
 return [x/sum(z) for x in z]
rng=random.Random(721)
checks=0
for n in [1,2,8,128]:
 for trial in range(100):
  types=[rng.randint(1,4) for _ in range(n)]; mask=[rng.random()>0.2 for _ in range(n)]
  if trial==0:mask=[False]*n
  if trial==1:types=[1]*n
  scores=[rng.uniform(-15,15) for _ in range(n)]
  ws=[weights(scores,types,mask,a) for a in (0,.5,1)]
  for w in ws:
   assert all(math.isfinite(x) and x>=0 for x in w)
   assert all(x==0 for x,m in zip(w,mask) if not m)
   assert math.isclose(sum(w),float(any(mask)),abs_tol=1e-12)
  counts={b:sum(m and t==b for t,m in zip(types,mask)) for b in range(1,5)}
  max_types={b for b,c in counts.items() if c==max(counts.values())}
  masses=[sum(wi for wi,t in zip(w,types) if t in max_types) for w in ws]
  assert masses[0]+1e-12>=masses[1]>=masses[2]-1e-12
  for b,count in counts.items():
   if not count:continue
   conditional=[]
   for w in ws:
    mass=sum(wi for wi,t in zip(w,types) if t==b)
    conditional.append([wi/mass if t==b else 0 for wi,t in zip(w,types)])
   assert all(abs(x-y)<1e-12 for w in conditional[1:] for x,y in zip(w,conditional[0]))
  for alpha in (0,.5,1):
   w=weights([0.0]*n,types,mask,alpha)
   total=sum(c**(1-alpha) for c in counts.values() if c)
   for b,count in counts.items():
    expected=(count**(1-alpha))/total if count else 0
    assert abs(sum(wi for wi,t in zip(w,types) if t==b)-expected)<1e-12
  if len({t for t,m in zip(types,mask) if m})<=1:
   assert all(abs(x-y)<1e-12 for w in ws[1:] for x,y in zip(w,ws[0]))
  checks+=1
print('Proposal conforms to the exposed schema and variant contract. Two Model classes are AST-identical.')
print(checks,'independent scalar-algebra cases pass (empty/padding, single-type, conditional type invariance, pooling reductions and largest-count type mass). These are not Torch execution tests.')
PY"

